from pathlib import Path
import json,html
W=Path(__file__).resolve().parent
JOBS=[('revised-stage6-harrier','Stage 6 / Harrier and Nightwing','Turning turrets, higher crossing helpers, and the native second life.'),('revised-stage6-rebels','Stage 6 / Rebel Fighters','Allies during the intro and Rook’s heading-matched gun pods.'),('final-stage7-dredger','Stage 7 / Caustic Dredger','Rapid toxic dual guns, dorsal mortar arcs and native Furious overdrive.'),('stage7-warden-final','Stage 7 / Toxic Warden','Reachable rear limbs and canisters, protected core, swats and final hopping state.'),('final-stage8-herald','Stage 8 / Herald of Death','Side passes, red tornado storm, skull nuke, lightning rage and bouncing code sigil.')]
cards=[];data=[]
for folder,title,desc in JOBS:
 d=json.loads((W/folder/'report.json').read_text());assert d['completed'],(folder,d['reason']);assert not d['pageErrors']and not d['assetErrors']and not any('draw error'in str(c).lower()for c in d['consoleErrors']);assert not d['audio'].get('deaths',0)
 stage=d['stage'];video=f'{folder}/stage{stage}-furious.mp4';assert(W/video).exists();duration=d['timeline'][-1]['seconds'];data.append({'id':folder,'title':title,'video':video,'duration':duration,'completed':True,'deaths':d['audio'].get('deaths'),'audioPeakPreCaptureGain':d['audio']['peak'],'frames':d['audio']['frames'],'nativeFrames':d['timeline'][-1]['nativeFrames'],'consoleMessages':d['consoleErrors']})
 cards.append(f'''<article><h2>{html.escape(title)}</h2><p>{html.escape(desc)}</p><video controls preload="metadata" playsinline src="{video}" poster="{folder}/frame-0008.png"></video><p class="proof">FURIOUS · COLE · GOD INPUT BOT · NATIVE HEALTH / PHASES · {duration:.1f}s · COMPLETE · 0 BOT DEATHS</p></article>''')
(W/'film-summary.json').write_text(json.dumps(data,indent=2))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BOF / Encounter Revision Review</title><style>body{margin:0;background:#080e18;color:#e6eff8;font:16px system-ui}main{max-width:1180px;margin:auto;padding:28px}h1{font-size:27px}h2{font-size:21px}p{color:#b7c7d9;line-height:1.5}article{border:1px solid #37516a;padding:20px;margin:28px 0;background:#0e1928}video,img{width:100%;height:auto;display:block}video{aspect-ratio:16/10;background:#02050a}a{color:#7ddcff}.proof{font-size:12px;color:#e1be7b}nav{display:flex;gap:20px;flex-wrap:wrap}</style><main><h1>Bullets of Fury / Encounter Revision</h1><p>Fresh live-engine recordings of the revised fights. The input bot uses native GOD mode; enemy health, damage, transitions and defeat remain the game’s own rules. Herald’s opening demonstration holds player fire so the complete new attack cycle is visible.</p><nav><a href="REPORT.md">Change and verification report</a><a href="http://127.0.0.1:59944/index.html">Pixelmap font experiment</a><a href="video-checks.json">Video playback checks</a></nav><p>The aborted Warden diagnostics and superseded Herald take are preserved separately and excluded here. Human difficulty still needs playtesting. The required assertion suite retains its same five pre-existing failures.</p>'''+''.join(cards)+'''<article><h2>Authored bank preview</h2><img src="authored-banks-preview.png" alt="Native turret, limb, core and newly generated Herald effect frames"></article></main></html>'''
(W/'index.html').write_text(page,encoding='utf-8');print('Created review gallery for',len(data),'native clear videos.')
